package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.singlecell.SoupXAmbient;
import org.jlinalg.singlecell.TfidfMarkers;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;
import static org.jlinalg.cli.SoupXWorkflowTransport.*;

/** Independent complete-population/profile/mask/exposure audits; original optimizers/correction stay upstream. */
final class SoupXWorkflowAudit {
    private SoupXWorkflowAudit() { }
    static void constructed(Path worker,SoupXWorkflowInputs.Population p,SoupXWorkflowRequest.Request r,Meter meter)throws IOException{
        counts(sparse(worker.resolve("constructed-raw.json"),r,meter),p.raw(),meter);counts(sparse(worker.resolve("constructed-filtered.json"),r,meter),p.filtered(),meter);
        Table profile=table(worker.resolve("soup-profile.json"),r,meter);require(profile.tokens("gene_id").equals(p.raw().genes()),"Original soup-profile gene order differs");for(int g=0;g<profile.rows();g++){meter.spend(1);require(profile.number("counts",g)==p.profile().counts().get(g),"Original selected-droplet gene count differs");near(profile.number("est",g),p.profile().fractions().get(g),"Original selected-droplet fraction differs");}metadata(table(worker.resolve("constructed-metadata.json"),r,meter),p,r,meter);
    }
    private static void counts(Sparse source,SoupXAmbient.Counts expected,Meter meter)throws IOException{require(source.rows().equals(expected.genes())&&source.columns().equals(expected.cells()),"Original constructed count axes differ");for(var e:source.values().entrySet()){meter.spend(1);int g=(int)(e.getKey()/source.columns().size()),c=(int)(e.getKey()%source.columns().size());require(e.getValue()==expected.count(g,c),"Original constructed count value differs");}for(var e:expected.entries()){meter.spend(1);require(source.get(e.gene(),e.cell())==e.count(),"Original constructed count is missing/changed");}}
    private static void metadata(Table metadata,SoupXWorkflowInputs.Population p,SoupXWorkflowRequest.Request r,Meter meter)throws IOException{require(metadata.tokens("cell_id").equals(p.filtered().cells()),"Original cell metadata order differs");require(metadata.columns().containsKey("clusters")==r.clusters().equals("supplied"),"Original cluster presence differs");if(r.clusters().equals("supplied"))require(metadata.tokens("clusters").equals(p.clusters()),"Original cluster labels differ");for(int c=0;c<metadata.rows();c++){meter.spend(1);require(metadata.number("nUMIs",c)==p.filtered().columnTotal(c),"Original filtered-cell total differs");}}
    static Map<String,Object> analysis(Path target,Map<String,Object> a,SoupXWorkflowInputs.Population p,SoupXWorkflowRequest.Request r,Meter meter)throws IOException{
        var state=read(target.resolve("source-status.json"),r);require(text(state.get("id")).equals(text(a.get("id")))&&bool(state.get("returned")),"Original case did not return completely");var e=object(a.get("estimation"));String kind=text(e.get("kind"));boolean correction=a.get("adjustment")!=null;require(text(state.get("estimator")).equals(kind)&&bool(state.get("correction_requested"))==correction&&bool(state.get("corrected_counts_produced"))==correction,"Original case kind/correction disposition differs");require(integer(state.get("seed"),0,2147483647)==integer(a.get("seed"),0,2147483647),"Original RNG seed differs");require(strings(state.get("RNG"),3).equals(List.of("Mersenne-Twister","Inversion","Rejection")),"Original RNG kind differs");Table metadata=table(target.resolve("metadata.json"),r,meter);metadata(metadata,p,r,meter);boolean hasRho=metadata.columns().containsKey("rho");boolean expectedRho=!kind.equals("automatic-legacy-density")||bool(e.get("apply_density_mode"));require(hasRho==expectedRho,"Original estimator return-type/rho application differs");var report=new LinkedHashMap<String,Object>();report.put("id",text(a.get("id")));report.put("estimator",kind);report.put("cells",metadata.rows());report.put("original_warnings",diagnostic(state.get("warnings"),r.intermediateEntries()));report.put("original_messages",diagnostic(state.get("messages"),r.intermediateEntries()));report.put("correction_requested",correction);report.put("automatic_estimator_or_count_correction_independently_refitted",false);
        if(hasRho)for(int c=0;c<metadata.rows();c++){double rho=metadata.number("rho",c);require(rho>=0&&rho<=1,"Original rho outside[0,1] retained but not admitted; no clipping");}
        switch(kind){
            case "fixed"->{for(int c=0;c<metadata.rows();c++){meter.spend(1);double expected=text(e.get("rho_mode")).equals("constant")?finite(e.get("rho"),0,1):p.fixedRho().get(c);require(metadata.number("rho",c)==expected,"Original supplied fixed rho differs");}}
            case "manual-global-poisson"->manual(target,e,metadata,p,r,meter,report);
            case "automatic-gamma","automatic-legacy-density"->automatic(target,e,metadata,p,r,meter,report);
            default->throw new IOException("Unexpected validated estimator");
        }
        if(correction){Sparse corrected=sparse(target.resolve("corrected-counts.json"),r,meter);require(corrected.rows().equals(p.filtered().genes())&&corrected.columns().equals(p.filtered().cells()),"Original corrected matrix axes differ");boolean rounded=bool(object(a.get("adjustment")).get("round_to_integer"));double total=0;
            for(var v:corrected.values().entrySet()){meter.spend(1);int g=(int)(v.getKey()/corrected.columns().size()),c=(int)(v.getKey()%corrected.columns().size());double value=v.getValue();require(value>=0&&value<=p.filtered().count(g,c),"Original corrected value outside its observed count; preserve source return, no clipping/admission");if(rounded)require(value==Math.rint(value),"Original requested integer rounding differs");total+=value;}
            report.put("corrected_stored_entries",corrected.values().size());report.put("corrected_count_total",total);report.put("every_corrected_coordinate_and_MatrixMarket_value_audited",true);
        }else require(!Files.exists(target.resolve("corrected-counts.json"))&&!Files.exists(target.resolve("corrected-counts.mtx")),"Unexpected corrected output for estimation-only request");
        long nonfinite=0;for(Column column:metadata.columns().values())for(String value:column.kinds()){meter.spend(1);if(!value.equals("value"))nonfinite++;}report.put("original_nonfinite_metadata_fields_retained",nonfinite);return report;
    }
    private static SoupXAmbient.Budget nativeBudget(Meter meter)throws IOException{require(meter.used<meter.maximum,"Native audit operation capacity exhausted");return new SoupXAmbient.Budget(meter.maximum-meter.used);}
    private static void manual(Path target,Map<String,Object> e,Table metadata,SoupXWorkflowInputs.Population p,SoupXWorkflowRequest.Request r,Meter meter,Map<String,Object> report)throws IOException{
        SoupXAmbient.Mask mask=p.mask();if(text(e.get("mask_mode")).equals("estimate")){var budget=nativeBudget(meter);mask=SoupXAmbient.nonExpressing(p.filtered(),p.profile(),p.geneSets(),text(e.get("clustering_scope")).equals("cell-only")?null:p.clusters(),finite(e.get("maximum_contamination"),0,1),finite(e.get("fdr"),0,1),r.intermediateEntries(),budget);meter.spend(budget.used());}
        Table originalMask=table(target.resolve("nonexpression-mask.json"),r,meter);require(originalMask.tokens("cell_id").equals(p.filtered().cells()),"Original non-expression mask row order differs");require(new ArrayList<>(originalMask.columns().keySet()).equals(join("cell_id",mask.geneSets())),"Original mask gene-set order differs");
        for(int c=0;c<mask.cells().size();c++)for(int g=0;g<mask.geneSets().size();g++){meter.spend(1);require(originalMask.logical(mask.geneSets().get(g),c)==mask.accepted().get(c).get(g),"Original/manual non-expression mask differs; inspect Poisson/BH numerical boundaries and retain original outputs");}
        var budget=nativeBudget(meter);var analytical=SoupXAmbient.globalPoisson(p.filtered(),p.profile(),p.geneSets(),mask,budget);meter.spend(budget.used());var fit=read(target.resolve("fit-summary.json"),r);require(text(fit.get("kind")).equals("original-global-Poisson-GLM")&&bool(fit.get("converged")),"Original global Poisson fit did not converge");double rho=number(text(fit.get("rho")));for(int c=0;c<metadata.rows();c++)require(metadata.number("rho",c)==rho,"Original GLM coefficient/metadata differs");Table observations=table(target.resolve("glm-observations.json"),r,meter);require(observations.rows()==analytical.acceptedCellSets(),"Original GLM observation population differs");var expected=observations(p,mask,meter);require(expected.size()==observations.rows(),"Original GLM input shape differs");
        for(int i=0;i<expected.size();i++){meter.spend(1);double[] row=expected.get(i);require(observations.number("observed",i)==row[0],"Original GLM observed count differs");near(observations.number("log_exposure",i),Math.log(row[1]),"Original GLM offset differs");near(observations.number("fitted",i),rho*row[1],"Original GLM fitted response differs");}
        report.put("analytical_Poisson_rho_diagnostic",analytical.rho());report.put("original_GLM_rho_retained",rho);report.put("original_minus_analytical",rho-analytical.rho());report.put("original_score_diagnostic",analytical.observed()-rho*analytical.exposure());report.put("original_iterations",integer(fit.get("iterations"),1,100000));report.put("original_epsilon",finite(fit.get("epsilon"),0,1));report.put("manual_mask_cell_sets",analytical.acceptedCellSets());report.put("original_GLM_or_confidence_intervals_independently_refitted",false);
    }
    private static List<double[]> observations(SoupXWorkflowInputs.Population p,SoupXAmbient.Mask mask,Meter meter)throws IOException{var result=new ArrayList<double[]>();int j=0;for(var e:p.geneSets().entrySet()){var indices=new ArrayList<Integer>();double fraction=0;for(String gene:e.getValue()){int g=p.filtered().genes().indexOf(gene);indices.add(g);fraction+=p.profile().fractions().get(g);}for(int c=0;c<p.filtered().cells().size();c++)if(mask.accepted().get(c).get(j)){double count=0;for(int g:indices){meter.spend(1);count+=p.filtered().count(g,c);}result.add(new double[]{count,p.filtered().columnTotal(c)*fraction});}j++;}return result;}
    private static void automatic(Path target,Map<String,Object> e,Table metadata,SoupXWorkflowInputs.Population p,SoupXWorkflowRequest.Request r,Meter meter,Map<String,Object> report)throws IOException{
        boolean current=text(e.get("kind")).equals("automatic-gamma");Table estimates=table(target.resolve(current?"auto-estimates.json":"legacy-auto-table.json"),r,meter);require(estimates.rows()>0,"Original automatic estimator returned no estimates");List<String> genes=estimates.tokens("gene");var targets=new ArrayList<>(new LinkedHashSet<>(genes));var clusterSet=new TreeSet<String>(CiceroWorkflowInputs.C_ORDER);clusterSet.addAll(p.clusters());var clusters=new ArrayList<>(clusterSet);require((long)targets.size()*clusters.size()==estimates.rows(),"Original automatic gene/cluster population differs");require(targets.size()<=integer(e.get(current?"maximum_markers":"number_markers"),1,1000000),"Original automatic marker count exceeds selected maximum");var groups=new LinkedHashMap<String,List<String>>();for(String g:targets){require(p.filtered().genes().contains(g),"Original automatic marker absent from complete genes");groups.put(g,List.of(g));}
        double maximum=current?finite(list(e.get("contamination_range")).get(1),0,1):finite(e.get("rho_max"),0,1),fdr=finite(e.get(current?"rho_max_fdr":"fdr"),0,1);var budget=nativeBudget(meter);var mask=SoupXAmbient.nonExpressing(p.filtered(),p.profile(),groups,p.clusters(),maximum,fdr,r.intermediateEntries(),budget);meter.spend(budget.used());double[] lowerTails=new double[estimates.rows()],q=new double[estimates.rows()];Integer[] order=new Integer[estimates.rows()];int used=0;
        for(int c=0;c<clusters.size();c++){var cells=new ArrayList<Integer>();double total=0;for(int i=0;i<p.clusters().size();i++)if(p.clusters().get(i).equals(clusters.get(c))){cells.add(i);total+=p.filtered().columnTotal(i);}for(int g=0;g<targets.size();g++){meter.spend(1);int at=c*targets.size()+g;require(genes.get(at).equals(targets.get(g)),"Original automatic table must retain gene-major rows within cluster blocks");int gene=p.filtered().genes().indexOf(targets.get(g));double observed=0;for(int cell:cells){meter.spend(1);observed+=p.filtered().count(gene,cell);}double exposure=p.profile().fractions().get(gene)*total;require(exposure>0,"Automatic marker has zero soup exposure");require(estimates.number("obsCnt",at)==observed,"Original automatic observed cluster count differs");near(estimates.number("expCnt",at),exposure,"Original automatic cluster exposure differs");near(estimates.number(current?"rhoEst":"rho",at),observed/exposure,"Original automatic count/exposure ratio differs");boolean pass=mask.accepted().get(cells.get(0)).get(g);require(estimates.logical("passNonExp",at)==pass,"Original automatic non-expression flag differs; inspect native/source numerical boundary");lowerTails[at]=jdistlib.Poisson.cumulative(observed,exposure*maximum,true,false);order[at]=at;}}
        Arrays.sort(order,(a,b)->{try{meter.spend(1);}catch(IOException failure){throw new java.io.UncheckedIOException(failure);}return Double.compare(lowerTails[a],lowerTails[b]);});double minimum=1;for(int at=order.length-1;at>=0;at--){meter.spend(1);int i=order[at];minimum=Math.min(minimum,((double)order.length/(at+1))*lowerTails[i]);q[i]=minimum;}
        for(int i=0;i<q.length;i++){meter.spend(1);String field=current?"isExpressedFDR":"qVal";near(estimates.number(field,i),q[i],"Original automatic lower-tail BH value differs");boolean expected=current?estimates.logical("passNonExp",i):estimates.number("obsCnt",i)>=finite(e.get("minimum_counts"),0,9007199254740991.0)&&estimates.number(field,i)<finite(e.get("fdr"),0,1)&&estimates.logical("passNonExp",i);require(estimates.logical(current?"useEst":"pass",i)==expected,"Original automatic estimate-selection flag differs");if(expected)used++;}
        require(used>0,"Original automatic fit has no accepted estimates");double rho;
        if(current){var fit=read(target.resolve("fit-summary.json"),r);require(text(fit.get("kind")).equals("original-current-gamma"),"Unexpected original current fit kind");rho=number(text(fit.get("rho")));require(number(text(fit.get("prior_rho")))==finite(e.get("prior_rho"),Double.MIN_NORMAL,1)&&number(text(fit.get("prior_rho_sd")))==finite(e.get("prior_rho_sd"),Double.MIN_NORMAL,1e12),"Original gamma prior choices differ");Table posterior=table(target.resolve("auto-posterior.json"),r,meter);require(posterior.rows()==1001,"Original gamma probe grid differs");double best=-1,chosen=Double.NaN;var range=list(e.get("contamination_range"));double lo=finite(range.get(0),0,1),hi=finite(range.get(1),0,1);for(int i=0;i<posterior.rows();i++){meter.spend(1);double x=posterior.number("rho",i),density=posterior.number("posterior",i);near(x,i/1000.0,"Original gamma probe differs");require(density>=0,"Negative original posterior density");if(x>=lo&&x<=hi&&density>best){best=density;chosen=x;}}require(rho==chosen,"Original gamma posterior-grid maximum selection differs");markers(table(target.resolve("auto-markers.json"),r,meter),e,p,meter);}
        else{rho=estimates.number("rhoEst",0);for(int i=0;i<estimates.rows();i++)require(estimates.number("rhoEst",i)==rho,"Original density mode is not a unique repeated estimate");report.put("legacy_density_mode_applied",bool(e.get("apply_density_mode")));}
        if(metadata.columns().containsKey("rho"))for(int c=0;c<metadata.rows();c++)require(metadata.number("rho",c)==rho,"Original automatic global rho differs from fit return");report.put("original_automatic_rho",rho);report.put("automatic_gene_cluster_rows",estimates.rows());report.put("automatic_accepted_estimates",used);report.put("automatic_gamma_posterior_or_density_independently_refitted",false);
    }
    private static void markers(Table table,Map<String,Object> e,SoupXWorkflowInputs.Population p,Meter meter)throws IOException{
        require(meter.used<meter.maximum,"Marker audit budget exhausted");var budget=new TfidfMarkers.Budget(meter.maximum-meter.used);var entries=new ArrayList<TfidfMarkers.Entry>();for(var v:p.filtered().entries())entries.add(new TfidfMarkers.Entry(v.gene(),v.cell(),v.count()));var result=TfidfMarkers.calculate(p.filtered().genes(),p.filtered().cells(),p.clusters(),entries,-1,.01,.9,(long)p.filtered().genes().size()*p.clusters().size(),budget);meter.spend(budget.used());var rows=new HashMap<List<String>,TfidfMarkers.Row>();for(var row:result.statistics())rows.put(List.of(row.gene(),row.cluster()),row);var seen=new HashSet<String>();double previous=Double.POSITIVE_INFINITY;
        for(int i=0;i<table.rows();i++){meter.spend(1);String gene=table.tokens("gene").get(i),cluster=table.tokens("cluster").get(i);require(seen.add(gene),"Original current marker deduplication differs");var row=rows.get(List.of(gene,cluster));require(row!=null,"Original current marker axes differ");near(table.number("geneFrequency",i),row.frequency(),"Original marker frequency differs");near(table.number("geneFrequencyOutsideCluster",i),row.outsideFrequency(),"Original outside frequency differs");near(table.number("geneFrequencySecondBest",i),row.secondBestFrequency(),"Original second-best frequency differs");near(table.number("geneFrequencyGlobal",i),row.globalFrequency(),"Original global marker frequency differs");require(table.tokens("secondBestClusterName").get(i).equals(row.secondBestCluster()),"Original second-best marker cluster differs");near(table.number("tfidf",i),row.tfidf(),"Original marker TF-IDF differs");near(table.number("idf",i),row.idf(),"Original marker IDF differs");near(table.number("qval",i),row.qValue(),"Original marker BH q differs");double score=table.number("tfidf",i);require(score>finite(e.get("tfidf_min"),0,1e12)&&table.number("qval",i)<.01&&score<=previous,"Original current marker cutoff/order differs");previous=score;}
    }
    private static List<String> join(String first,List<String> rest){var out=new ArrayList<String>();out.add(first);out.addAll(rest);return out;}
    private static List<String> diagnostic(Object raw,int maximum)throws IOException{var values=list(raw);require(values.size()<=maximum,"Diagnostic population exceeds capacity");var result=new ArrayList<String>();for(Object value:values)result.add(text(value));return List.copyOf(result);}
}
